*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_List", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "List" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("List"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "List" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("List")))).length === 0)); } }, { id: "tr_143", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "List" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("List"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "List" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("List")))).length === 0)); } }, { id: "tr_153", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "List" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("List"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "List" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("List")))).length === 0)); } }, { id: "if_List_2", fn: function(){ return ((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "List" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("List"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "List" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("List")))).length === 0)); } }, { id: "tr_163", fn: function(){ return ((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "List" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("List"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "List" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("List")))).length === 0)); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_name_2", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("name"))); } },
        { childId: "cal_endDate", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("endDate"))); } },
        { childId: "__rb1", fn: function () { return String(dma_personInfo.get("jobtitlNm")) + String(dma_personInfo.get("comAbbrv")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init = function () {
    /* sdd-asis-lifecycle:begin init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const f = (document.form || { elements: [] });
    const id = $c.util.getComponent("id_news");
    if ($c.util.getComponent('dma_submitReq').get('newsScrollY') !== '') {
        document.body.scrollTop = $c.util.getComponent('dma_submitReq').get('newsScrollY');
    }
    if ('null' === 'end') {

    }
    if ('null' === '' && 'null' === '' && 'null' === '') {
        $c.util.getComponent("ipt_check1").setValue(true);
        $c.util.getComponent("ipt_check2").setValue(true);
        $c.util.getComponent("ipt_check3").setValue(true);
    }
    if ('null' === '' && 'null' === '') {
        setPeriod('12');
        f.strDate.value = "20010101";
    }
    /* sdd-asis-lifecycle:end */
};


