/**
 * @method
 * @name scwin.findPosY
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.findPosY = function (obj) {
    /* sdd-asis-lifecycle:begin findPosY — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let curtop = 0;
    if (obj.offsetParent) {
        while (obj.offsetParent) {
            curtop += obj.offsetTop;
            obj = obj.offsetParent;
        }
    } else {
        if (obj.y) {
            curtop += obj.y;
        }
    }
    return curtop;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.submit
 * @author Inswave
 * @date 2026. 09. 29
 * @param mode
 * @returns
 * @hidden N
*/
scwin.submit = async function (mode) {
    /* sdd-asis-lifecycle:begin submit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const f = (document.form || { elements: [] });
    if (($c.util.getComponent('ipt_name_2').getValue() == null ? '' : String($c.util.getComponent('ipt_name_2').getValue())) === '') {
        await $c.win.alert("성명을 입력해 주세요.");
        $c.util.getComponent("ipt_name_2").focus();
        return;
    }
    f.action = "/PersonInfo.do";
    $c.util.getComponent('dma_submitReq').set('method', "personSearchList");
    if ((String($c.util.getComponent('ipt_check1').getValue() || "") !== "")) {
        $c.util.getComponent("dma_submitReq").set("jrKind1", "00");
    }
    if ((String($c.util.getComponent('ipt_check2').getValue() || "") !== "")) {
        $c.util.getComponent("dma_submitReq").set("jrKind2", encodeURI("대표이사"));
    }
    if ((String($c.util.getComponent('ipt_check3').getValue() || "") !== "")) {
        $c.util.getComponent("dma_submitReq").set("jrKind3", "02");
    }
    if (mode == null) {
        $c.util.getComponent('dma_submitReq').set('newsScrollY', "");
        $c.util.getComponent('dma_submitReq').set('pageNum', "1");
    }
    $c.util.getComponent("ipt_name_2").setValue(encodeURI($c.util.getComponent('ipt_name_2').getValue()));
    $c.util.getComponent("dma_submitReq").set("birthday", $c.util.getComponent("dma_submitReq").get("birthday").replace(/\./g, ""));
    await scwin.tx_submit();

    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.findSameName
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.findSameName = async function () {
    /* sdd-asis-lifecycle:begin findSameName — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (($c.util.getComponent('ipt_name_2').getValue() == null ? '' : String($c.util.getComponent('ipt_name_2').getValue())) === '') {
        await $c.win.alert("이름을 입력하여 주세요.");
        return;
    }
    const f = (document.frm || { elements: [] });
    f.target = "REGULAR";
    $c.util.getComponent("ipt_name_2").setValue(encodeURI($c.util.getComponent('ipt_name_2').getValue()));
    f.action = "/PersonInfo.do";
    $c.util.getComponent('dma_submitReq').set('method', "findSameName");
    await scwin.tx_findSameName();
    /* sdd-asis-lifecycle:end */
};


